package com.masterclass.inventory.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.OffsetDateTime; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(NotFoundException.class) ResponseEntity<ApiError> notFound(NotFoundException e){return build(HttpStatus.NOT_FOUND,e.getMessage(),List.of());} @ExceptionHandler(BusinessException.class) ResponseEntity<ApiError> business(BusinessException e){return build(HttpStatus.CONFLICT,e.getMessage(),List.of());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e){var d=e.getBindingResult().getFieldErrors().stream().map(f->f.getField()+": "+f.getDefaultMessage()).toList();return build(HttpStatus.BAD_REQUEST,"Validation failed",d);} @ExceptionHandler(Exception.class) ResponseEntity<ApiError> generic(Exception e){return build(HttpStatus.INTERNAL_SERVER_ERROR,"Unexpected error",List.of(e.getClass().getSimpleName()));} private ResponseEntity<ApiError> build(HttpStatus s,String m,List<String>d){return ResponseEntity.status(s).body(new ApiError(OffsetDateTime.now(),s.value(),s.getReasonPhrase(),m,d));} }
